  function getRuleById(id) {
    var rules = getRules();
    var numId = parseInt(id, 10);
    for (var i = 0; i < rules.length; i++) {
      if (rules[i].id === numId) return rules[i];
    }
    return null;
  }

  function getNextRuleId() {
    var rules = getRules();
    var max = 0;
    for (var i = 0; i < rules.length; i++) {
      if (rules[i].id > max) max = rules[i].id;
    }
    return max + 1;
  }

